export const updateApplicationDetails = <ThrowOnError extends boolean = false>(options: Options<UpdateApplicationDetailsData, ThrowOnError>) => (options.client ?? client).patch<UpdateApplicationDetailsResponses, UpdateApplicationDetailsErrors, ThrowOnError>({
    requestValidator: async (data) => await zUpdateApplicationDetailsData.parseAsync(data),
    responseType: 'json',
    responseValidator: async (data) => await zUpdateApplicationDetailsResponse.parseAsync(data),
    url: '/applications/{applicationId}/details',
    ...options,
    headers: {
        'Content-Type': 'application/json-patch+json',
        ...options.headers
    }
});
